        {
            Console.WriteLine("weekly");
        var total = 0;
        foreach (var line in lines)
        {
            total += line.Length;
        }

        Console.WriteLine("lines " + lines.Count);
        Console.WriteLine("characters " + total);
        Console.WriteLine("average " + total / Math.Max(1, lines.Count));
        }
    }
}

duplicate-code.good:
using System;
using System.Collections.Generic;

namespace Sample
{
    public class Report
    {
        public void Daily(List<string> lines)
        {
            Console.WriteLine("daily");
            Summarize(lines);
        }

        public void Weekly(List<string> lines)
        {
            Console.WriteLine("weekly");
            Summarize(lines);
        }

        private static void Summarize(List<string> lines)
        {
        var total = 0;
        foreach (var line in lines)
        {
            total += line.Length;
        }

        Console.WriteLine("lines " + lines.Count);
        Console.WriteLine("characters " + total);
        Console.WriteLine("average " + total / Math.Max(1, lines.Count));
        }
    }
}

