using System.Threading;

namespace Sample
{
    public class Sample
    {
        private readonly object _gate = new();

        public void Update(bool skip)
        {
            Monitor.Enter(_gate);
            try
            {
                if (skip)
                {
                    return;
                }
            }
            finally
            {
                Monitor.Exit(_gate);
            }
        }
