zip-slip.good:
using System;
using System.IO;
using System.IO.Compression;

namespace Sample
{
    public class Sample
    {
        public void Extract(ZipArchive archive)
        {
            foreach (var entry in archive.Entries)
            {
                var target = Path.GetFullPath(Path.Combine("/out", entry.FullName));
                if (!target.StartsWith("/out/", StringComparison.Ordinal))
                {
                    continue;
                }

                entry.ExtractToFile(target);
            }
        }
    }
}
